import { mkdir, readFile, writeFile } from "node:fs/promises";
import { dirname } from "node:path";
import { fileURLToPath } from "node:url";

import openapiTS, { astToString } from "openapi-typescript";

const source = new URL("../../../api/admin.openapi.yaml", import.meta.url);
const target = new URL("../src/generated/admin-api.ts", import.meta.url);
const check = process.argv.includes("--check");
const header = [
  "// Generated from api/admin.openapi.yaml by scripts/generate-admin-api.mjs.",
  "// Do not edit this file directly; run `pnpm generate:api`.",
  ""
].join("\n");

const ast = await openapiTS(source, {
  alphabetize: true,
  silent: true
});
const generated = `${header}${astToString(ast)}`;

if (check) {
  let current;
  try {
    current = await readFile(target, "utf8");
  } catch {
    console.error("Generated Admin API types are missing. Run `pnpm generate:api`.");
    process.exitCode = 1;
  }
  if (current !== undefined && current !== generated) {
    console.error("Generated Admin API types are stale. Run `pnpm generate:api`.");
    process.exitCode = 1;
  }
} else {
  await mkdir(dirname(fileURLToPath(target)), { recursive: true });
  await writeFile(target, generated, "utf8");
}
